package au.aumanet.app;

import java.nio.*;import java.security.*;import java.util.*;import org.json.*;

/** Dedicated checked-radio domain. No raw-signing or discovery authority. */
final class GatewayRadioConfigCodec {
 static final int QUERY=136,REPORT=232,COMMAND=224,MAX_FRAME=321;static final long FRESH_MS=5000;
 private static final int[][] OPTIONS={{28,22,50,1,916000000},{30,22,50,1,917000000},{32,22,50,1,918000000},{34,22,50,1,919000000},{36,22,50,1,920000000},{38,22,50,1,921000000},{40,22,50,1,922000000},{42,22,50,1,923000000},{44,22,50,1,924000000},{46,22,50,1,925000000},{48,22,50,1,926000000},{50,22,50,1,927000000},{29,23,51,2,916500000},{33,23,51,2,918500000},{37,23,51,2,920500000},{41,23,51,2,922500000},{45,23,51,2,924500000},{49,23,51,2,926500000},{31,24,52,4,917500000},{39,24,52,4,921500000},{47,24,52,4,925500000},{35,25,53,8,919500000},{43,25,53,8,923500000}};
 static JSONObject option(int id)throws JSONException{if(id<1||id>OPTIONS.length)throw invalid();int[] r=OPTIONS[id-1];return new JSONObject().put("id",id).put("channel",r[0]).put("operatingClass",r[1]).put("globalOperatingClass",r[2]).put("bandwidthMHz",r[3]).put("centerFrequencyHz",r[4]);}
 static JSONArray options()throws JSONException{JSONArray a=new JSONArray();for(int i=1;i<=OPTIONS.length;i++)a.put(option(i));return a;}
 static final class Message {
  final char kind;final String target,group,owner,relay,challenge,run,nonce,transaction;final long epoch,generation,remaining;final int current,persisted,trial,state,actual,power,error,operation;final boolean associated,station,persistenceKnown,canChange;private final byte[] raw;
  Message(byte[] b){raw=b.clone();kind=(char)b[5];target=hex(b,16,16,false);group=hex(b,32,16,false);epoch=number(b,48);owner=hex(b,56,32,true);relay=hex(b,88,16,false);challenge=hex(b,104,32,true);run=kind=='Q'?"":hex(b,136,16,false);nonce=kind=='Q'?"":hex(b,152,32,true);transaction=kind=='Q'?"":hex(b,184,16,false);generation=kind=='Q'?0:number(b,200);current=kind=='R'?b[208]&255:0;persisted=kind=='R'?b[209]&255:0;trial=kind=='R'?b[210]&255:kind=='C'?b[209]&255:0;state=kind=='R'?b[211]&255:0;remaining=kind=='R'?Integer.toUnsignedLong(ByteBuffer.wrap(b).getInt(212)):0;actual=kind=='R'?b[216]&255:0;associated=kind=='R'&&b[217]==1;station=kind=='R'&&b[218]==1;persistenceKnown=kind=='R'&&(b[219]&1)!=0;canChange=kind=='R'&&(b[219]&2)!=0;error=kind=='R'?Short.toUnsignedInt(ByteBuffer.wrap(b).getShort(220)):0;power=kind=='R'?b[224]&255:0;operation=kind=='C'?b[208]&255:0;}
  byte[] body(){return raw.clone();}
 }
 static Message parse(byte[] b){if(b==null||b.length<QUERY||b[0]!='A'||b[1]!='U'||b[2]!='G'||b[3]!='W'||b[4]!='C'||b[6]!='1'||b[7]!=0||b[8]!=1)throw invalid();char k=(char)b[5];if(b.length!=(k=='Q'?QUERY:k=='R'?REPORT:k=='C'?COMMAND:0))throw invalid();zero(b,9,7);nonzero(b,16,16);nonzero(b,32,16);nonzero(b,56,32);nonzero(b,88,16);nonzero(b,104,32);if(number(b,48)<1)throw invalid();if(k!='Q'){nonzero(b,136,16);nonzero(b,152,32);number(b,200);}if(k=='R'){if((b[208]&255)>23||(b[209]&255)>23||(b[210]&255)>23||(b[211]&255)>6||Integer.toUnsignedLong(ByteBuffer.wrap(b).getInt(212))>30000||(b[216]&255)>23||(b[217]&255)>1||(b[218]&255)>1||(b[219]&255)>3||Short.toUnsignedInt(ByteBuffer.wrap(b).getShort(222))!=1||(b[224]&255)<1||(b[224]&255)>24)throw invalid();if(b[218]==1&&((b[219]&2)!=0||b[209]!=0))throw invalid();zero(b,225,7);}else if(k=='C'){nonzero(b,184,16);if((b[208]&255)<1||(b[208]&255)>3||(b[209]&255)<1||(b[209]&255)>23)throw invalid();zero(b,210,14);}return new Message(b);}
 static Message query(String target,String group,long epoch,String owner,String relay,String challenge){return parse(prefix('Q',QUERY,target,group,epoch,owner,relay,challenge));}
 static Message command(Message report,String tx,int op,int target){if(report.kind!='R'||report.station||!report.canChange)throw invalid();byte[] b=prefix('C',COMMAND,report.target,report.group,report.epoch,report.owner,report.relay,report.challenge);put(b,136,GatewayGrantCodec.identifier(report.run));put(b,152,GatewayBootCodec.bytes(report.nonce,32));put(b,184,GatewayGrantCodec.identifier(tx));ByteBuffer.wrap(b).putLong(200,report.generation);b[208]=(byte)op;b[209]=(byte)target;return parse(b);}
 static boolean sameCommon(Message a,Message b){return a.target.equals(b.target)&&a.group.equals(b.group)&&a.epoch==b.epoch&&a.owner.equals(b.owner)&&a.relay.equals(b.relay)&&a.challenge.equals(b.challenge);}
 static final class Frame{final Message message;final byte[] signature;Frame(Message m,byte[] s){message=m;signature=s;}boolean verify(PublicKey key)throws Exception{GatewayPublicKeyPolicy.checked(key);Signature v=Signature.getInstance("SHA256withECDSA");v.initVerify(key);v.update(message.raw);return v.verify(signature);}}
 static byte[] envelope(Message m,byte[] signature){signature(signature);return ByteBuffer.allocate(17+m.raw.length+signature.length).put(GatewayGrantCodec.identifier(m.target)).put(m.raw).put((byte)signature.length).put(signature).array();}
 static Frame frame(byte[] data,int length){if(data==null||length>data.length||length>MAX_FRAME||length<QUERY+25)throw invalid();byte[] b=Arrays.copyOf(data,length);int size=b[21]=='Q'?QUERY:b[21]=='R'?REPORT:b[21]=='C'?COMMAND:0;if(size==0||length<size+25)throw invalid();int count=b[16+size]&255;if(length!=17+size+count)throw invalid();Message m=parse(Arrays.copyOfRange(b,16,16+size));if(!m.target.equals(hex(b,0,16,false)))throw invalid();byte[] sig=Arrays.copyOfRange(b,17+size,length);signature(sig);return new Frame(m,sig);}
 private static void signature(byte[] s){/* Reuse the strict P256 DER scalar validator in the frozen boot codec. */GatewayBootCodec.envelope(GatewayBootCodec.query("11111111111111111111111111111111","22222222222222222222222222222222",1,"AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA","11111111111111111111111111111111","BBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBB"),s);}
 private static byte[] prefix(char kind,int length,String target,String group,long epoch,String owner,String relay,String challenge){if(epoch<1||epoch>GroupNamePolicy.MAX_REVISION)throw invalid();byte[] b=new byte[length];put(b,0,new byte[]{'A','U','G','W','C',(byte)kind,'1',0,1});put(b,16,GatewayGrantCodec.identifier(target));put(b,32,GatewayGrantCodec.identifier(group));ByteBuffer.wrap(b).putLong(48,epoch);put(b,56,GatewayBootCodec.bytes(owner,32));put(b,88,GatewayGrantCodec.identifier(relay));put(b,104,GatewayBootCodec.bytes(challenge,32));return b;}
 private static long number(byte[] b,int p){long n=ByteBuffer.wrap(b).getLong(p);if(n<0||n>GroupNamePolicy.MAX_REVISION)throw invalid();return n;}private static String hex(byte[] b,int p,int n,boolean upper){String s=GroupWire.hex(Arrays.copyOfRange(b,p,p+n));return upper?s:s.toLowerCase(Locale.ROOT);}private static void zero(byte[] b,int p,int n){for(int i=p;i<p+n;i++)if(b[i]!=0)throw invalid();}private static void nonzero(byte[] b,int p,int n){for(int i=p;i<p+n;i++)if(b[i]!=0)return;throw invalid();}private static void put(byte[] b,int p,byte[] v){System.arraycopy(v,0,b,p,v.length);}private static IllegalArgumentException invalid(){return new IllegalArgumentException("Invalid checked radio control");}
 private GatewayRadioConfigCodec(){}
}
